def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    out = [row[:] for row in grid]
    # Join the outermost marked cells in each shared row and column.
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if out[r][c] == bg:
                    out[r][c] = 3
    return out
